'use strict';
// Verify intrinsic TIR at the newly reachable 50/350 mm stations by rotating a
// circle and intersecting an external probe. This is not a held total dial TIR.
const fs=require('node:fs'),path=require('node:path');process.chdir(path.resolve(__dirname,'..'));
function stream(seed){let state=(seed^0x49535031)>>>0;return()=>{state=(state+0x6D2B79F5)>>>0;let v=state;v=Math.imul(v^(v>>>15),v|1);v^=v+Math.imul(v^(v>>>7),v|61);return((v^(v>>>14))>>>0)/4294967296;};}
function teachingVectors(profile){const next=stream(profile.seed),used=profile.condition==='used',radial=(a,b)=>{const radius=a+(b-a)*next(),angle=2*Math.PI*next();return[radius*Math.cos(angle),radius*Math.sin(angle)];};return{eccentricity:radial(used?1:.5,used?6:2.5),tilt:radial(used?5:2,used?40:15)};}
function expectedTIR(profile,axialMm){const v=teachingVectors(profile),offset=v.eccentricity.map((x,i)=>(x+v.tilt[i]*axialMm/1000)/1e6),phase=-Math.atan2(offset[1],offset[0]);
 function extension(angle){const c=[offset[0]*Math.cos(angle)-offset[1]*Math.sin(angle),offset[0]*Math.sin(angle)+offset[1]*Math.cos(angle)],distance=t=>Math.hypot(.035-t-c[0],c[1])-.025;let lo=0,hi=.02;for(let i=0;i<70;i++){const m=(lo+hi)/2;if(distance(m)>0)lo=m;else hi=m;}return(lo+hi)/2;}
 const extremes=[extension(phase),extension(phase+Math.PI)];return{raw:(Math.max(...extremes)-Math.min(...extremes))*1e6,extremes,phase,vectors:v};}
module.exports={teachingVectors,expectedTIR};
if(require.main===module){const product=require('../src/intrinsic-inspection.js'),rows=[];for(const condition of ['new','used'])for(const seed of [0,1,123456,4294967295])for(const axialMm of [50,350]){const profile={version:1,condition,seed},given=product.fromProfile(profile).runout,actual=product.runoutAt(given.eccentricityMicrons,given.tiltMicroradians,axialMm),expected=expectedTIR(profile,axialMm),error=actual-expected.raw;rows.push({condition,seed,axialMm,actual,expected:expected.raw,error,integer:Math.round(expected.raw)});}const failures=rows.filter(r=>Math.abs(r.error)>1e-7),summary={scope:'50/350 mm intrinsic component only. Input seed independently decoded, expected values from rotating-circle external contact extrema. No support-held total TIR claim.',cases:rows.length,maxErrorUm:Math.max(...rows.map(r=>Math.abs(r.error))),failureCount:failures.length};fs.writeFileSync('docs/qa-fixtures-20261011/independent-tir-50-350.json',JSON.stringify({summary,failures,rows},null,2)+'\n');console.log(JSON.stringify(summary));if(failures.length)process.exitCode=1;}
function expectedSurface(profile){const rng=stream(profile.seed);for(let i=0;i<4;i++)rng();const points=[1,0,-1].flatMap(back=>[-1,0,1].map(x=>({x,back}))),heights=points.map(()=>((profile.condition==='used'?12:4)*(2*rng()-1))),A=points.map(p=>[1,p.x,p.back]),aug=Array.from({length:3},(_,i)=>[...Array.from({length:3},(_,j)=>A.reduce((sum,row)=>sum+row[i]*row[j],0)),A.reduce((sum,row,k)=>sum+row[i]*heights[k],0)]);
 // General normal-equation solve. No symmetric-grid shortcut or product plane.
 for(let col=0;col<3;col++){let pivot=col;for(let r=col+1;r<3;r++)if(Math.abs(aug[r][col])>Math.abs(aug[pivot][col]))pivot=r;[aug[col],aug[pivot]]=[aug[pivot],aug[col]];const d=aug[col][col];for(let j=col;j<4;j++)aug[col][j]/=d;for(let r=0;r<3;r++)if(r!==col){const m=aug[r][col];for(let j=col;j<4;j++)aug[r][j]-=m*aug[col][j];}}
 const plane=aug.map(row=>row[3]),residual=heights.map((h,k)=>h-A[k].reduce((sum,x,j)=>sum+x*plane[j],0)),zero=residual[3],values=residual.map(x=>x-zero);return{values,range:Math.max(...values)-Math.min(...values),rawHeights:heights,plane};}
module.exports.expectedSurface=expectedSurface;
